/// <summary>
/// The worktree registered at <paramref name="root"/>, or walking up parent
/// directories to find a registered ancestor repo (matching real git's
/// repository-discovery behaviour for <c>rev-parse --show-toplevel</c> and
/// other commands invoked from a subdirectory). Returns null when no
/// ancestor is a registered repo.
/// </summary>
public static Worktree? Find(string root)
{
    var current = Normalize(root);
    while (true)
    {
        if (Worktrees.TryGetValue(current, out var wt))
            return wt;
        var parent = Path.GetDirectoryName(current);
        if (parent is null || parent == current)
            return null;
        current = parent;
    }
}

